import React from 'react'
import './Styles.css';

function FaculltyOption({ name, designation }) {
    return (
        <div className="w-auto h-auto m-[20px] p-[20px] border-2 shadow-xl rounded-xl hover:scale-105 duration-300">

            <img src="https://w7.pngwing.com/pngs/329/705/png-transparent-teacher-student-education-tutor-faculty-teacher-class-expert-recruiter-thumbnail.png" alt="alt" />

            <h3>{name}</h3>

            <p>{designation}</p>

        </div>
    )
}

export default FaculltyOption
